\label{prop:minsol}
Assume that all parameters $\tilde{\alpha}_{N,n}$, $\alpha_{N,n}$, and $\beta_N$ are positive. Then there exist unique minimizers $\Phi_N\in\textnormal{Pol}_{N}$ and $\tilde{\Psi}_N\in\textnormal{Pol}_{\lfloor\kappa N\rfloor}$ of the functional $\mathcal{F}$ in \eqref{eqn:mineq2} that are determined by the symbols $\phi=(\Phi_N^\wedge(1)\sigma_1,\ldots,\Phi_N^\wedge(N)\sigma_{N},\tilde{\Phi}_{N}^\wedge(1),\ldots,\tilde{\Phi}_{N}^\wedge(\lfloor\kappa N\rfloor))^T$ which solve the linear equations
\begin{align}\label{eqn:lineq1}
\mathbf{M}\phi=\alpha,
\end{align}
where 
\begin{align}
\mathbf{M}=\left(\begin{array}{c|c}\mathbf{D}_1+\mathbf{P}_1&-\mathbf{P}_2\\\hline-\mathbf{P}_3&\mathbf{D}_2+\mathbf{P}_4\end{array}\right),
\end{align}
and $\alpha=(\alpha_{N,1},\ldots,\alpha_{N,N},\tilde{\alpha}_{N,1},\ldots,\tilde{\alpha}_{N,\lfloor\kappa N\rfloor})^T$. The diagonal matrices $\mathbf{D}_1$, $\mathbf{D}_2$ are given by 
\begin{align}
\mathbf{D}_1=\textnormal{diag}\left(\frac{\beta_N}{\sigma_n^2}+\alpha_{N,n}\right)_{n=0,\ldots,N}, \qquad\mathbf{D}_2=\textnormal{diag}\big(\tilde{\alpha}_{N,n}\big)_{n=0,\ldots,\lfloor\kappa N\rfloor},
\end{align}
whereas $\mathbf{P}_1$,\ldots, $\mathbf{P}_4$ are submatrices of the Gram matrix $\big(P_{n,m}^\rho\big)_{n,m=0,\ldots, \lfloor\kappa N\rfloor}$. More precisely,
\begin{align}
\mathbf{P}_1=\big(P_{n,m}^\rho\big)_{n,m=0,\ldots,N},&\qquad \mathbf{P}_2=\big(P_{n,m}^\rho\big)_{n=0,\ldots,N\atop m=0,\ldots,\lfloor\kappa N\rfloor},
\\\mathbf{P}_3=\big(P_{n,m}^\rho\big)_{n=0,\ldots,\lfloor\kappa N\rfloor\atop m=0,\ldots,N},&\qquad\mathbf{P}_4=\big(P_{n,m}^\rho\big)_{n,m=0,\ldots,\lfloor\kappa N\rfloor}.
\end{align}
with
\begin{align}
P_{n,m}^\rho=\frac{(2n+1)(2m+1)}{2}\int_{-1}^{1-\rho}P_n(t)P_m(t)dt.
\end{align}

First we observe that the representation \eqref{eqn:psin} of the kernel $\tilde{\Psi}_N$ and its zonality together with the addition theorem for spherical harmonics imply 
\small
\begin{align}\label{eqn:psinorm}
&8\pi^2 r^4\left\|\tilde{\Psi}_N\right\|^2_{L^2([-1,1-\rho])}
\\&=\frac{8\pi^2 r^4}{r^4}\int_{-1}^{1-\rho}\Bigg|\sum_{n=0}^{\lfloor\kappa N\rfloor}\frac{2n+1}{4\pi}\left(\tilde{\Phi}_{N}^\wedge(n)-\Phi_N^\wedge(n)\sigma_n\right)P_n(t)\Bigg|^2dt\nonumber
\\&=\sum_{n=0}^{\lfloor\kappa N\rfloor}\sum_{m=0}^{\lfloor\kappa N\rfloor}\frac{(2n+1)(2m+1)}{2}\left(\tilde{\Phi}_{N}^\wedge(m)-\Phi_N^\wedge(m)\sigma_m\right)\left(\tilde{\Phi}_{N}^\wedge(n)-\Phi_N^\wedge(n)\sigma_n\right)\int_{-1}^{1-\rho}\!\!\!\!\!\!\!P_n(t)P_m(t)dt\nonumber
\\&=\sum_{n=0}^{\lfloor\kappa N\rfloor}\sum_{m=0}^{\lfloor\kappa N\rfloor}\left(\tilde{\Phi}_{N}^\wedge(m)-\Phi_N^\wedge(m)\sigma_m\right)\left(\tilde{\Phi}_{N}^\wedge(n)-\Phi_N^\wedge(n)\sigma_n\right)P_{n,m}^\rho.\nonumber
\end{align}
\normalsize
Inserting \eqref{eqn:psinorm} into \eqref{eqn:mineq2} and then differentiating the whole expression with respect to $\Phi_N^\wedge(n)\sigma_n$ and $\tilde{\Phi}_{N}^\wedge(n)$ leads to 
\begin{align}
-2\alpha_{N,n}(1-\Phi_N^\wedge(n)\sigma_n)+2\beta_N\frac{\Phi_N^\wedge(n)\sigma_n}{\sigma_n^2}-2\sum_{m=0}^{\lfloor\kappa N\rfloor}\left(\tilde{\Phi}_{N}^\wedge(m)-\Phi_N^\wedge(m)\sigma_m\right)P_{n,m}^\rho,
\end{align} 
for $n=0,\ldots,N$, and
\begin{align}
-2\tilde{\alpha}_{N,n}(1-\tilde{\Phi}_{N}^\wedge(n))+2\sum_{m=0}^{\lfloor\kappa N\rfloor}\left(\tilde{\Phi}_{N}^\wedge(m)-\Phi_N^\wedge(m)\sigma_m\right)P_{n,m}^\rho,
\end{align}
for $n=0,\ldots,\lfloor\kappa N\rfloor$, respectively. Setting the two expressions above equal to zero, a proper reordering leads to the linear equation \eqref{eqn:lineq1}. At last, we observe that the matrix $(P_{n,m}^\rho)_{n,m=0,\ldots,\lfloor\kappa N\rfloor}$ is positive definite (since it represents a Gram matrix of linearly independent functions) and that all appearing diagonal matrices are positive definite due to positive matrix entries. Thus, the matrix $\mathbf{M}$ is positive definite and the linear system \eqref{eqn:lineq1} is uniquely solvable and leads to a minimum of \eqref{eqn:mineq2}.

\label{prop:loc1} 
If $F\in\mathcal{H}_s(\Omega_r)$, $s\geq 2$, it holds that
\begin{align}\label{eqn:locprop}
\lim_{N\to\infty}\left\|\int_{\Omega_r\setminus\mathcal{C}_r(\rho,\cdot)}\tilde{\Psi}^{Sh}_N(\cdot,y)F(y)d\omega(y)\right\|_{L^2 (\Omega_r)}=0,
\end{align}
where $\tilde{\Psi}^{Sh}_N$ is the Shannon-type kernel with symbols $\big(\tilde{\Psi}_N^{Sh}\big)^\wedge(n)=1$, if $N +1\leq n\leq \lfloor\kappa N\rfloor$, and $\big(\tilde{\Psi}_N^{Sh}\big)^\wedge(n)=0$, else.

\label{thm:convres}
Assume that the parameters $\alpha_{N,n}$, $\tilde{\alpha}_{N,n}$, and $\beta_N$ are positive and suppose that, for some fixed $\delta>0$ and $\kappa>1$,
\begin{align}
\inf_{n=0,\ldots, \lfloor\kappa N\rfloor}\frac{\beta_N\frac{1-\left(\frac{R}{r}\right)^{2(N+1)}}{1-\left(\frac{R}{r}\right)^2}+( \lfloor\kappa N\rfloor+1)^2}{{\alpha}_{N,n}}&=\mathcal{O}\left(N^{-2(1+\delta)}\right),\quad \textit{ for }N\to\infty.\label{eqn:ass1}
\end{align}
The same relation shall hold true for $\tilde{\alpha}_{N,n}$. Additionally, let every $N$ be associated with an $\varepsilon_1=\varepsilon_1(N)>0$ and an $\varepsilon_2=\varepsilon_2(N)>0$ such that 
\begin{align}
\lim_{N\to\infty}\varepsilon_1 \left(\frac{R}{r}\right)^{N}=\lim_{N\to\infty}\varepsilon_2 \,{N}=0.\label{eqn:propx}
\end{align}
The functions $F_1:\Omega_R\to\mathbb{R}$ and $F_2:\Gamma_r\to\mathbb{R}$, $r<R$, are supposed to be such that a unique solution $U$ of \eqref{eqn:11}--\eqref{eqn:13} exists and that the restriction $U^+$ is of class $\mathcal{H}_s(\Omega_r)$, for some fixed $s\geq 2$. The erroneous input data is given by $F_1^{\ensuremath{\varepsilon}_1}=F_1+\ensuremath{\varepsilon}_1 E_1$ and $F_2^{\ensuremath{\varepsilon}_2}=F_2+\ensuremath{\varepsilon}_2 E_2$, with $E_1\in L^2(\Omega_R)$ and $E_2\in L^2(\Omega_r)$. If the kernels $\Phi_N\in\textnormal{Pol}_{N}$ and kernel $\tilde{\Psi}_N\in\textnormal{Pol}_{ \lfloor\kappa N\rfloor}$ are the minimizers of the functional $\mathcal{F}$ from \eqref{eqn:mineq2} and if $U_N^\ensuremath{\varepsilon}$ is given as in \eqref{eqn:firstapprox3}, then
\begin{align}
\lim_{N\to\infty}\left\|U^+-U_ {N}^{\varepsilon}\right\|_{L^2(\tilde{\Gamma}_r)}=0.\label{eqn:convres}
\end{align}

As an auxiliary set of kernels, we define the Shannon-type kernels $\Phi_N^{Sh}$ and $\tilde{\Psi}_N^{Sh}$ via the symbols
\begin{align}
\big(\Phi_N^{Sh}\big)^\wedge(n)=\left\{\begin{array}{ll}\frac{1}{\sigma_n},&n\leq N,\\0,&\textnormal{else},\end{array}\right.\qquad \big(\tilde{\Phi}_{N}^{Sh}\big)^\wedge(n)=\left\{\begin{array}{ll}1,&n\leq \lfloor\kappa N\rfloor,\\0,&\textnormal{else},\end{array}\right.
\end{align}
and $\big(\tilde{\Psi}_N^{Sh}\big)^\wedge(n)=\big(\tilde{\Phi}_N^{Sh}\big)^\wedge(n)-\big(\Phi_N^{Sh}\big)^\wedge(n)\sigma_n$. $\Phi_N^{Sh}$ represents the kernel of the so-called truncated singular value decomposition for the downward continuation operator ${T}^{down}$. By using the addition theorem for spherical harmonics and properties of the Legendre polynomials, we obtain
\begin{align}
\mathcal{F}(\Phi_N^{Sh},\tilde{\Psi}_N^{Sh})&=\beta_N\sum_{n=0}^{N}\frac{1}{\sigma_n^2}+8\pi^2 r^4\big\|\tilde{\Psi}_N^{Sh}\big\|^2_{L^2([-1,1-\rho])}\label{eqn:shannonest}
\\&\leq \beta_N\frac{1-\left(\frac{R}{r}\right)^{2(N+1)}}{1-\left(\frac{R}{r}\right)^{2}}+8\pi^2\sum_{n=0}^{\lfloor\kappa N\rfloor}\left(\frac{2n+1}{4\pi}\right)^2\left\|P_n\right\|^2_{L^2([-1,1])}\nonumber
\\&= \beta_N\frac{1-\left(\frac{R}{r}\right)^{2(N+1)}}{1-\left(\frac{R}{r}\right)^{2}}+(\lfloor\kappa N\rfloor+1)^2.\nonumber
\end{align}
The kernels that minimize $\mathcal{F}$ are denoted by $\Phi_N$ and $\tilde{\Psi}_N$. In consequence,
\begin{align}
\tilde{\alpha}_{N,n}\big(1-\tilde{\Phi}_{N}^\wedge(n)\big)^2&\leq\mathcal{F}(\Phi_N,\tilde{\Psi}_N)\leq \mathcal{F}(\Phi_N^{Sh},\tilde{\Psi}_N^{Sh})
\\&\leq \beta_N\frac{1-\left(\frac{R}{r}\right)^{2(N+1)}}{1-\left(\frac{R}{r}\right)^{2}}+(\lfloor\kappa N\rfloor+1)^2,\nonumber
\end{align}
for all $n\leq \lfloor\kappa N\rfloor$. In combination with \eqref{eqn:ass1}, this leads to
\begin{align}\label{eqn:conphij}
\big|1-\tilde{\Phi}_{N}^\wedge(n)\big|= \mathcal{O}(N^{-1-\delta}),
\end{align}
uniformly for all $n\leq \lfloor\kappa N\rfloor$ and $N\to\infty$. The estimate $|1-\Phi_N^\wedge(n)\sigma_n|=\mathcal{O}(N^{-1-\delta})$ follows in the same manner and holds uniformly for all $n\leq N$ and $N\to\infty$. Finally, since $\tilde{\Phi}_{N}^\wedge(n)=0$ for $n> \lfloor\kappa N\rfloor$, we end up with
\begin{align}
\lim_{N\to\infty}\sup_{n=0,1,\ldots}\frac{|1-\tilde{\Phi}_{N}^\wedge(n)|}{(n+\frac{1}{2})^{s}}=0,
\end{align}
which shows that the first term on the right hand side of the error estimate \eqref{eqn:errorestfinal} vanishes. The second term can be treated analogously. 

Due to the uniform boundedness of $|\Phi_J^\wedge(n)\sigma_n|$, there exists some constant $C>0$ such that \eqref{eqn:propx} implies
\begin{align}
\lim_{N\to\infty}\ensuremath{\varepsilon}_1\sup_{n=0,1,\ldots}\left|\Phi_N^\wedge(n)\right|\leq C\lim_{N\to\infty}\ensuremath{\varepsilon}_1\left(\frac{R}{r}\right)^{N}=0.
\end{align}
so that the third term on the right hand side of \eqref{eqn:errorestfinal} vanishes as well. The fourth term does not vanish. However, taking a closer look at the derivation of this term, we see that it suffices to show that $\big\|\sum_{n=0}^\infty\sum_{k=1}^{2n+1}\tilde{\Psi}_{N}^\wedge(n)F_r^\wedge(n,k)\frac{1}{r}Y_{n,k}\big\|_{L^2(\Omega_r)}$ tends to zero (where $F$ stands for $U^+$ or $E_2$). Using the previous results and $|\tilde{\Psi}_N^\wedge(n)|\leq |1-{\Phi}_N^\wedge(n)\sigma_n|+|1-\tilde{\Phi}_N^\wedge(n)|$, it follows that
\begin{align}
\left\|\sum_{n=0}^\infty\sum_{k=1}^{2n+1}\tilde{\Psi}_{N}^\wedge(n)F_r^\wedge(n,k)\frac{1}{r}Y_{n,k}\right\|_{L^2(\Omega_r)}^2\leq \mathcal{O}(N^{-2\delta})+C\sum_{n=N+1}^{\lfloor \kappa N\rfloor}\sum_{k=1}^{2n+1}\left|F_r^\wedge(n,k)\right|^2,
\end{align}
for some constant $C>0$. Latter vanishes for $N\to\infty$ since $F$ (i.e., $U^+$ or $E_2$) is of class $L^2(\Omega_r)$. In order to handle the last term of the error estimate \eqref{eqn:errorestfinal}, it has to be shown that $\|\tilde{\Psi}_N\|_{L^2([-1,1-\rho])}$ tends to zero. This, again, is generally not true. But, taking a closer look at the derivation of the estimate indicates that it suffices to show that
\small\begin{align}\label{eqn:altterms}
\Bigg\|\,\,\int_{\Omega_r\setminus\mathcal{C}_r(\rho,\cdot)}\tilde{\Psi}_{N}(\cdot,y) U^+(y)d\omega(y)\Bigg\|_{L^2(\Omega_r)}, \qquad \ensuremath{\varepsilon}_2\Bigg\|\,\,\int_{\Omega_r\setminus\mathcal{C}_r(\rho,\cdot)}\tilde{\Psi}_{N}(\cdot,y) E_2(y)d\omega(y)\Bigg\|_{L^2(\Omega_r)}
\end{align}\normalsize
vanish as $N\to\infty$. For the left expression we obtain
\begin{equation}\label{eqn:locest}
\begin{aligned}
&\Bigg\|\,\,\int_{\Omega_r\setminus\mathcal{C}_r(\rho,\cdot)}\tilde{\Psi}_{N}(\cdot,y) U^+(y)d\omega(y)\Bigg\|_{L^2(\Omega_r)}
\\&\leq\Bigg\|\,\,\int_{\Omega_r\setminus\mathcal{C}_r(\rho,\cdot)}\tilde{\Psi}^{Sh}_{N}(\cdot,y) U^+(y)d\omega(y)\Bigg\|_{L^2(\Omega_r)}
\\&\quad\,+\Bigg\|\,\,\int_{\Omega_r\setminus\mathcal{C}_r(\rho,\cdot)}\left(\tilde{\Psi}^{Sh}_{N}(\cdot,y)-\tilde{\Psi}_{N}(\cdot,y)\right) U^+(y)d\omega(y)\Bigg\|_{L^2(\Omega_r)}
\\&\leq\Bigg\|\,\,\int_{\Omega_r\setminus\mathcal{C}_r(\rho,\cdot)}\tilde{\Psi}^{Sh}_{N}(\cdot,y) U^+(y)d\omega(y)\Bigg\|_{L^2(\Omega_r)}
\\&\quad\,+2\pi r^2\|\tilde{\Psi}^{Sh}_{N}-\tilde{\Psi}_{N}\|_{L^2([-1,1-\rho])} \|U^+\|_{L^1(\Omega_r)},
\end{aligned}
\end{equation}
where Young's inequality has been used in the last row. Since $U^+\in \mathcal{H}_s(\Omega_r)$, $s\geq 2$, Proposition \ref{prop:loc1} implies that the first term on the right hand side of \eqref{eqn:locest} tends to zero as $N\to\infty$. The second term on the right hand side of \eqref{eqn:locest} can be treated as follows 
\begin{equation}
\begin{aligned}
&\big\|\tilde{\Psi}^{Sh}_{N}-\tilde{\Psi}_{N}\big\|_{L^2([-1,1-\rho])}^2
\\&\leq\sum_{n=0}^{\lfloor\kappa N\rfloor}\left(\frac{2n+1}{4\pi}\right)^2\left|\tilde{\Psi}_N^\wedge(n)-\left(\tilde{\Psi}^{Sh}_N\right)^\wedge(n)\right|^2\|P_n\|_{L^2([-1,1])}^2
\\&\leq\sum_{n=0}^{\lfloor\kappa N\rfloor}\frac{2n+1}{8\pi^2}\left|\left|\tilde{\Phi}_{N}^\wedge(n)-1\right|+\left|{\Phi}_N^\wedge(n)\sigma_n-1\right|\chi_{[0,N]}(n)\right|^2
\\&=\sum_{n=0}^{\lfloor\kappa N\rfloor}\frac{2n+1}{8\pi^2}\mathcal{O}\left(N^{-2(1+\delta)}\right)=\mathcal{O}\left(N^{-2\delta}\right).
\end{aligned}
\end{equation}
By $\chi_{[0,N]}(n)$ we mean the characteristic function, i.e., it is equal to 1 if $n=0,\ldots,N$, and equal to 0 otherwise. In conclusion, the left expression in \eqref{eqn:altterms} vanishes as $N\to\infty$. For the right expression in \eqref{eqn:altterms}, we obtain the desired result in a similar but easier manner. Finally, combining all steps of the proof, we have shown that the right hand side of the error estimate \eqref{eqn:errorestfinal} converges to zero, which yields \eqref{eqn:convres}.

\label{rem:lockernels}
The condition $U^+\in \mathcal{H}_s(\Omega_r)$, $s\geq 2$, in Theorem \ref{thm:convres} can be relaxed to $U^+\in \mathcal{H}_s(\Omega_r)$, $s>0$, if the minimizing functional $\mathcal{F}$ in \eqref{eqn:mineq2} is substituted by
\begin{align}\label{eqn:mineq3}
\mathcal{F}_{Filter}(\Phi_N,\tilde{\Psi}_N)=&\sum_{n=0}^{\lfloor \kappa N\rfloor}\tilde{\alpha}_{N,n}\big|K_N^\wedge(n)-\tilde{\Phi}_{N}^\wedge(n)\big|^2+\sum_{n=0}^{N}\alpha_{N,n}\big|K_N^\wedge(n)-{\Phi}_{N}^\wedge(n)\sigma_n\big|^2
\\&+\beta_N\sum_{n=0}^{N}\big|\Phi_N^\wedge(n)\big|^2+8\pi^2 r^4\left\|\tilde{\Psi}_N\right\|^2_{L^2([-1,1-\rho])},\nonumber
\end{align}
where $K_N^\wedge(n)$ are the symbols of a filtered kernel (compare, e.g., \cite{yuguang132} and references therein for more information)
\begin{align}
\tilde{\Phi}_{N}^{Filter}(x,y)=\sum_{n=0}^{N}\sum_{k=1}^{2n+1}K_N^\wedge(n)Y_{n,k}\left(\frac{x}{|x|}\right)Y_{n,k}\left(\frac{y}{|y|}\right).
\end{align}
Then the proof of Theorem \ref{thm:convres} follows in a very similar manner as before, just that the minimizing kernels are not compared to the Shannon-type kernel but to the filtered kernel. Opposed to the Shannon-type kernel, an appropriately filtered kernel has the localization property $\lim_{N\to\infty}\|\tilde{\Phi}_{N}^{Filter}\|_{L^1([-1,1-\rho])}=0$  which makes the condition $s\geq 2$ on the smoothness of $U^+$ (required for Proposition \ref{prop:loc1}) obsolete.

\label{lem:loc}
Assume that the parameters $\alpha_{N,n}$, $\tilde{\alpha}_{N,n}$, and $\beta_N$ are positive and suppose that, for some fixed $\delta>0$ and $\kappa>1$,
\begin{align}
\inf_{n=0,\ldots, \lfloor\kappa N\rfloor}\frac{\beta_N\frac{1-\left(\frac{R}{r}\right)^{2(N+1)}}{1-\left(\frac{R}{r}\right)^2}+( \lfloor\kappa N\rfloor+1)^2}{{\alpha}_{N,n}}&=\mathcal{O}\left(N^{-2(1+\delta)}\right),\quad \textit{ for }N\to\infty.\label{eqn:ass11}
\end{align}
The same relation shall hold true for $\tilde{\alpha}_{N,n}$. If the scaling kernel $\Phi_N\in\textnormal{Pol}_{N}$ and the wavelet kernel $\tilde{\Psi}_N\in\textnormal{Pol}_{\lfloor\kappa N\rfloor}$ are the minimizers of the functional $\mathcal{F}$ from \eqref{eqn:mineq2}, then
\begin{align} \label{eqn:optloc2}
\lim_{N\to\infty}
\frac{\big\|\tilde{\Psi}_N\big\|^2_{L^2([-1,1-\rho])}}{\big\|\tilde{\Psi}_N\big\|^2_{L^2([-1,1])}}=0.
\end{align}

The function $F_N(t)={|\tilde{\Psi}_N(t)|^2}/{\|\tilde{\Psi}_N\|^2_{L^2([-1,1])}}$ can be regarded as the density function of a random variable $t\in[-1,1]$. Thus, we can write
\begin{align}
\frac{\big\|\tilde{\Psi}_N\big\|^2_{L^2([-1,1-\rho])}}{\big\|\tilde{\Psi}_N\big\|^2_{L^2([-1,1])}}&=\int_{-1}^{1-\rho}F_N(t)dt=P_N(t< 1-\rho)=1-P_N\big(t-E_N(t)\geq 1-\rho-E_N(t)\big)\nonumber
\\&\leq \frac{V_N(t)}{V_N(t)+ (1-\rho-E_N(t))^2},
\end{align}
where we have used Cantelli's inequality for the last estimate. By $P_N(t< a)$ we mean the probability (with respect to the density function $F_N$) that $t$ lies in the interval $[-1,a)$ while $P_N(t\geq a)$ means the probability of $t$ being in the interval $[a,1]$. Furthermore, $E_N(t)$ denotes the expected value of $t$ and $V_N(t)=E(t^2)-(E(t))^2$ the variance of $t$. In other words, we are done if we can show that $\lim_{N\to\infty}E_N(t)=1$ and $\lim_{N\to \infty}V_N(t)=0$. 

First, we use the addition theorem for spherical harmonics and the recurrence relation  $tP_n(t)=\frac{1}{2n+1}\left((n+1)P_{n+1}(t)+nP_{n-1}(t)\right)$ to obtain  
\begin{align}\label{eqn:et1}
\int_{-1}^1 t|\tilde{\Psi}_N(t)|^2 dt&= \frac{1}{r^2} \sum_{n=0}^{\lfloor\kappa N\rfloor}\sum_{m=0}^{\lfloor\kappa N\rfloor}\frac{2n+1}{4\pi}\frac{2m+1}{4\pi}\tilde{\Psi}_N^\wedge(n)\tilde{\Psi}_N^\wedge(m)\int_{-1}^1tP_n(t)P_m(t)dt
\\&=\sum_{n=0}^{\lfloor\kappa N\rfloor}\frac{2n+1}{16\pi^2r^2}\tilde{\Psi}_N^\wedge(n)\left(n\tilde{\Psi}_N^\wedge(n-1)+(n+1)\tilde{\Psi}_N^\wedge(n+1)\right)\int_{-1}^1|P_n(t)|^2 dt\nonumber
\\&=\frac{1}{8\pi^2r^2}\sum_{n=0}^{\lfloor\kappa N\rfloor}n\tilde{\Psi}_N^\wedge(n)\tilde{\Psi}_N^\wedge(n-1)+(n+1)\tilde{\Psi}_N^\wedge(n)\tilde{\Psi}_N^\wedge(n+1).\nonumber
\end{align}
From \eqref{eqn:conphij} and the corresponding estimate for $\Phi_N^\wedge(n)\sigma_n$ we find $|\tilde{\Psi}_N^\wedge(n)|^2=\mathcal{O}(N^{-2(1+\delta)})$ for $n\leq N$, and $|1-\tilde{\Psi}_N^\wedge(n)|^2=|1-\tilde{\Phi}_{N}^\wedge(n)|^2=\mathcal{O}(N^{-2(1+\delta)})$, for $N+1\leq n\leq \lfloor\kappa N\rfloor$. As a consequence,  \eqref{eqn:et1} implies
\begin{align}\label{eqn:et11}
&\int_{-1}^1 t|\tilde{\Psi}_N(t)|^2 dt
\\&=\mathcal{O}(N^{-2\delta})+\sum_{n=N+1}^{\lfloor\kappa N\rfloor} \frac{2n+1}{8\pi^2r^2}|\tilde{\Psi}_N^\wedge(n)|^2\left(\frac{n}{2n+1}\frac{\tilde{\Psi}_N^\wedge(n-1)}{\tilde{\Psi}_N^\wedge(n)}+\frac{n+1}{2n+1}\frac{\tilde{\Psi}_N^\wedge(n+1)}{\tilde{\Psi}_N^\wedge(n)}\right),\nonumber
\end{align}
where $\sup_{N+1\leq n\leq\lfloor \kappa N\rfloor}\big|1-\big(\frac{n}{2n+1}{\tilde{\Psi}_N^\wedge(n-1)}/{\tilde{\Psi}_N^\wedge(n)}+\frac{n+1}{2n+1}{\tilde{\Psi}_N^\wedge(n+1)}/{\tilde{\Psi}_N^\wedge(n)}\big)\big|\leq\varepsilon_N$, for  some $\varepsilon_N>0$ that satisfies $\varepsilon_N\to0$ as $N\to\infty$. The term $\|\tilde{\Psi}_N\|_{L^2([-1,1])}^2$ can be expressed similarly by
\begin{align}\label{eqn:et2}
\|\tilde{\Psi}_N\|_{L^2([-1,1])}^2=\sum_{n=0}^{\lfloor\kappa N\rfloor} \frac{2n+1}{8\pi^2r^2}|\tilde{\Psi}_N^\wedge(n)|^2=\mathcal{O}(N^{-2\delta})+\sum_{n=N+1}^{\lfloor\kappa N\rfloor} \frac{2n+1}{8\pi^2r^2}|\tilde{\Psi}_N^\wedge(n)|^2.
\end{align}
Thus, combining \eqref{eqn:et1}--\eqref{eqn:et2}, we obtain
\begin{align}
\lim_{N\to\infty}E_N(t)=\lim_{N\to\infty}\int_{-1}^1 t|F_N(t)| dt=\lim_{N\to\infty}\frac{\int_{-1}^1 t|\tilde{\Psi}_N(t)|^2 dt}{\|\tilde{\Psi}_N\|_{L^2([-1,1])}^2}=1.
\end{align}
In a similar fashion it can be shown that $\lim_{N\to\infty}E_N(t^2)=1$, implying $\lim_{N\to\infty}V_N(t)=0$, which concludes the proof.

\section{Numerical Test}\label{sec:num}

We generate a potential $U^+$ and data $F_1$, $F_2$ from uniformly distributed random Fourier coefficients up to spherical harmonic degree $100$. Analogously, the noise $E_1$, $E_2$ is produced by uniformly distributed random Fourier coefficients up to spherical harmonic degree $110$ and is then scaled such that $\|E_1\|_{L^2(\Omega_R)}=\|F_1\|_{L^2(\Omega_R)}$ and $\|E_2\|_{L^2(\Gamma_r)}=\|F_2\|_{L^2(\Gamma_r)}$. The mean Earth radius is given by $r=6371.2$km; for the satellite orbit we choose $R=7071.2$km (i.e., a satellite altitude of $700$km above the Earth's surface). We fix $N=100$ for the approximation $U_N^\varepsilon$ and choose $\kappa>0$ such that $\lfloor \kappa N\rfloor=130$. Then $U_N^\varepsilon$ is computed for the following different settings: 
\begin{itemize}
 \item[(a)] data $F_1^{\varepsilon_1}$ is available on an equiangular grid of $40804$ points on $\Omega_R$; data $F_2^{\varepsilon_2}$ is given on a Gauss-Legendre grid of $49062$ points in a spherical cap $\Gamma_r=\mathcal{C}_r(x_0,2\rho)$ around the North pole $x_0$. We choose $\tilde{\Gamma}_r=\mathcal{C}_r(x_0,\rho)$ and vary the radius $\rho\in\{0.5,0.02\}$, 
 \item[(b)] the parameters of the functional $\mathcal{F}$ are chosen among the cases $\beta_N\in\{10^{-3},\ldots,10^{4}\}$, $\tilde{\alpha}_{N,n}\in\{10^{1},\ldots, 10^{8}\}$, as well as ${\alpha}_{N,n}\in\{\tilde{\alpha}_{N,n},0.2\tilde{\alpha}_{N,n}\}$,

 \item[(c)] the noise level on $\Omega_R$ is varied among $\varepsilon_1\in\{0.001,0.01,0.05,0.1\}$; for the noise in $\Gamma_r$ we choose $\varepsilon_2\in\{\varepsilon_1,2\varepsilon_1,5\varepsilon_1\}$.
\end{itemize}
For the numerical integration required for the evaluation of $U_N^\varepsilon$ we use the scheme from \cite{drihea} on $\Omega_R$ and the scheme from \cite{womers12} in $\mathcal{C}_r(x,\rho)$. As a reference for the optimized kernels, an approximation $U_M^{\varepsilon,Sh}$ with Shannon-type kernels is computed as well: 
\begin{itemize}
 \item[(a)] we choose $\Phi_{M}^{Sh}$ with symbols $\big(\Phi_{M}^{Sh}\big)^\wedge(n)=\frac{1}{\sigma_n}$, if $n\leq M$, and $\big(\Phi_{M}^{Sh}\big)^\wedge(n)=0$, else, as well as $\tilde{\Psi}_{M}^{Sh}$ with symbols $\big(\tilde{\Psi}_{M}^{Sh}\big)^\wedge(n)=1$, if $M+1\leq n\leq 130$, and $\big(\tilde{\Psi}_{M}^{Sh}\big)^\wedge(n)=0$, else,
 \item[(b)] the cut-off degree $M$ is varied among $M\in\{0,2,4,\ldots,100\}$.
\end{itemize}
The Shannon-type kernels form a reasonable reference since the optimization of $\Phi_N$, $\tilde{\Psi}_N$ via $\mathcal{F}$ is done with respect to a Shannon-type situation. The relative errors $\|U_N^\varepsilon-U^+\|_{L^2(\tilde{\Gamma}_r)}/\|U^+\|_{L^2(\tilde{\Gamma}_r)}$ and $\|U_M^{\varepsilon,Sh}-U^+\|_{L^2(\tilde{\Gamma}_r)}/\|U^+\|_{L^2(\tilde{\Gamma}_r)}$ for the different situations are supplied in Tables \ref{tab:err1} and \ref{tab:err2}. 

As a comparison, we also compute approximations of $U^+$ using solely data $F_2$ in $\Gamma_r$ or solely data $F_1$ on $\Omega_R$, respectively. More precisely:
\begin{itemize}
 \item[(a)] spherical splines (based on the iterated Green function for the Beltrami operator; see, e.g., \cite{freeden81} and \cite{freeschrei09}) are applied for the approximation from local/regional data in $\Gamma_r$; for spherical cap radius $\rho=0.5$, we interpolate; for spherical cap radius $\rho=0.02$, we use a least square approach with smoothing parameter $\alpha=10^{-5}$ in order to deal with the ill-conditioned spline matrix (instead of a Gauss-Legendre grid, we choose approximately 30000 points in $\Gamma_r$ with similar spacing in longitudinal and latitudinal direction, avoiding concentration towards the poles and leading to better results for the spline method),
 \item[(b)] when using satellite data on $\Omega_R$ only, we apply the truncated singular value decomposition (TSVD) for different cut-off degrees $M\in\{0,2,4,\ldots,100\}$; in addition, the regularized collocation method (RCM) from \cite{naumov} with Tikhonov regularization is tested for different regularization parameters $\alpha\in\{10^{-7},\ldots,10^{-1}\}$ (the equiangular integration grid on $\Omega_R$ and the corresponding weights are the same as chosen before).
\end{itemize}

Tables \ref{tab:err4a} and \ref{tab:err4} indicate the results for the set of parameters that performed best for each of the methods above. We can make the following observations:
\begin{itemize}
\item[(1)] Tables  \ref{tab:err1} and \ref{tab:err2} show that the optimized kernels behave better than the Shannon-type kernels over the broad range of settings.
\item[(2)] The results in Table \ref{tab:err1} indicate the expected behaviour for the Shannon-type kernels: in the case $\varepsilon_1=\varepsilon_2$ only ground data is used (i.e., cut-off degree $M=0$), while the cut-off degree increases if the noise level of the ground data in $\Gamma_r$ is larger than for the satellite data on $\Omega_R$ (i.e., $\varepsilon_2>\varepsilon_1$). The same behaviour can be observed for the optimized kernels (cf. Figure \ref{fig:kernelplot}(a)), however, with a smoother transition between ground and satellite data: e.g., for the choice $\beta_n=3\cdot 10^3$, $\tilde{\alpha}_{N,n}=10^3$, ${\alpha}_{N,n}=10^3$, mostly ground data is used (i.e., $\tilde{\Psi}_N^\wedge(n)\approx 1$), but to a small extent (up to around spherical harmonic degree $n=10$) also satellite data is included (i.e., ${\Phi}_N^\wedge(n)\not=0$). This leads to an improvement of the relative error, e.g., by more than a factor two for the case $\ensuremath{\varepsilon}_1=\ensuremath{\varepsilon}_2=0.001$ (cf. Table \ref{tab:err1}(a)).
\item[(3)] If we reduce the spherical cap radius from $\rho=0.5$ to $\rho=0.02$, we find a similar behaviour as described in (2) (cf. Table \ref{tab:err2} and Figure \ref{fig:kernelplot}(b)). But we also find that for a small noise level $\varepsilon_1=0.001$ the relative error of the approximation is amplified significantly (by a factor of approximately $10$) while it behaves better for larger noise levels. Thus, the approximation error for small noise levels can be in first place accounted to an insufficient localization of the used kernels. Increasing the truncation degree $N$ of the scaling and wavelet kernels $\Phi_N$ and $\tilde{\Psi}_N$, respectively, according to the size of the region $\Gamma_r$ (i.e., according to the radius $\rho$) can compensate this problem.
\item[(4)] Table \ref{tab:err4a} shows that the results for splines that use only ground data in $\Gamma_r$ are comparable to the results for the optimized kernels from Tables \ref{tab:err1} and \ref{tab:err2}, at least if $\ensuremath{\varepsilon}_1=\ensuremath{\varepsilon}_2$. In case of higher noise levels in $\Gamma_r$ than on $\Omega_R$ (i.e., $\ensuremath{\varepsilon}_2>\ensuremath{\varepsilon}_1$), it becomes clear that the combination of ground and satellite data by optimized kernels yields improved results. Only for a small spherical cap radius $\rho=0.02$ and a small $\ensuremath{\varepsilon}_1=0.001$ (cf. Table \ref{tab:err2}), spherical splines behave significantly better than the optimized kernels. However, as already mentioned in (3), this can be overcome by increasing $N$ for the optimized kernels (noting that the splines that we use are non-band-limited).
\item[(5)] In Table \ref{tab:err4} we can see that for our test example pure downward continuation from satellite data on $\Omega_R$ yields significantly worse results than all other tested methods. This holds true especially for TSVD. RCM reveals a better behaviour but can compete with the other methods only for high noise levels and $\ensuremath{\varepsilon}_2$  significantly larger than $\ensuremath{\varepsilon}_1$ (e.g., $\ensuremath{\varepsilon}_1=0.1$ and $\ensuremath{\varepsilon}_2=5\ensuremath{\varepsilon}_1$). Remembering Remark \ref{rem:lockernels}, one might consider using the symbols of the Tikhonov kernel for the functional $\mathcal{F}$ instead of the symbols of Shannon-type kernels to obtain optimized kernels $\Phi_N$ and $\tilde{\Psi}_N$ that further improve the results for the latter situation.
\end{itemize}

\begin{rem}
Condition \eqref{eqn:ass1} suggests that the parameter $\beta_N$ should be significantly smaller than $\alpha_{N,n}$ and $\tilde{\alpha}_{N,n}$. This does not seem to be reflected by the parameters in Tables \ref{tab:err1} and \ref{tab:err2}. But Condition \eqref{eqn:propx} implies a relation between $N$ and $\ensuremath{\varepsilon}_1$, $\ensuremath{\varepsilon}_2$ that, for the choice $N=100$, leads to significantly smaller $\ensuremath{\varepsilon}_1$, $\ensuremath{\varepsilon}_2$ than those chosen in Tables \ref{tab:err1} and \ref{tab:err2}. Indeed, if we choose, e.g., $\ensuremath{\varepsilon}_1=\ensuremath{\varepsilon}_2=10^{-10}$  and repeat the above examples for $\rho=0.5$, we obtain a set of good parameters $\beta_N=10^{-6}$, $\alpha_{N,n}=10^4$, $\tilde{\alpha}_{N,n}=10^4$ that reflects the expected behaviour. However, our goal was to test realistic noise levels for the intended applications and show that the proposed method via optimized kernels works well for these scenarios.
\end{rem}

