\lim_{N\to\infty}\left\|b^+-b_ {N}^{\varepsilon}\right\|_{l^2(\tilde{\Gamma}_r)}=0.

\label{lem:lockernel2}
Assume that the parameters $\alpha_{N,n}$, $\tilde{\alpha}_{N,n}$, and $\beta_N$ are positive and suppose that, for some $\delta>0$ and $\kappa>1$,
\begin{align}
\inf_{n=0,\ldots, \lfloor \kappa N\rfloor}\frac{\beta_N\frac{1-\left(\frac{R}{r}\right)^{2(N+1)}}{1-\left(\frac{R}{r}\right)^2}+(\lfloor \kappa N\rfloor+1)^2}{{\alpha}_{N,n}}&=\mathcal{O}\left(N^{-2(1+\delta)}\right),\quad \textit{ for }N\to\infty.\label{eqn:ass5}
\end{align}
An analogous relation shall hold true for $\tilde{\alpha}_{N,n}$. If the scaling kernel $\mathbf{\Phi}_N\in\textnormal{\textbf{Pol}}_{N}$ and the wavelet kernel $\tilde{\mathbf{\Psi}}_N\in\textnormal{\textbf{Pol}}_{\lfloor \kappa N\rfloor}$ are the minimizers of the functional $\mathcal{F}$ from \eqref{eqn:mineq4}, then
\begin{align} \label{eqn:optloc3}
\lim_{N\to\infty}\frac{\big\|\tilde{\mathbf{\Psi}}_N\big\|^2_{L^2([-1,1-\rho])}}{\big\|\tilde{\mathbf{\Psi}}_N\big\|^2_{L^2([-1,1])}}=0.
\end{align}
